CREATE TABLE "better_supabase"."ai_chat_participants" ("chat_id" uuid NOT NULL, "user_id" uuid NOT NULL, "role" text NOT NULL DEFAULT 'viewer'::text, "added_by" uuid, "created_at" timestamp with time zone NOT NULL DEFAULT now(), CONSTRAINT "ai_chat_participants_pkey" PRIMARY KEY (chat_id, user_id), CONSTRAINT "ai_chat_participants_role_check" CHECK ((role = ANY (ARRAY['viewer'::text, 'editor'::text]))));

